/* Minimal hx-get shim — ~40 lines instead of a vendored library.
 *
 * The dashboard uses exactly one HTMX pattern: a button that GETs an HTML
 * fragment and swaps it into the DOM. Pulling in the full library would mean
 * either a CDN request (this project's defining constraint is that nothing
 * requires an external fetch) or vendoring 50 KB to use 2% of it.
 *
 * Supports: hx-get, hx-target, hx-swap (innerHTML | outerHTML), hx-indicator.
 * If the surface grows beyond this, vendor real HTMX rather than extending it.
 */
(function () {
  "use strict";

  function resolve(sel, el) {
    if (!sel) return el;
    if (sel === "this") return el;
    return document.querySelector(sel);
  }

  async function request(el) {
    var url = el.getAttribute("hx-get");
    if (!url) return;

    var target = resolve(el.getAttribute("hx-target"), el);
    if (!target) return;

    var indicator = resolve(el.getAttribute("hx-indicator"), el);
    // Hold the previous render at reduced opacity rather than flashing a
    // skeleton — no layout jump on refetch.
    if (indicator) indicator.classList.add("htmx-request");
    el.setAttribute("aria-busy", "true");

    try {
      var res = await fetch(url, { headers: { "HX-Request": "true" } });
      var html = await res.text();
      if (el.getAttribute("hx-swap") === "outerHTML") {
        target.outerHTML = html;
      } else {
        target.innerHTML = html;
      }
    } catch (err) {
      console.error("hx-get failed:", err);
      if (indicator) indicator.classList.remove("htmx-request");
      el.removeAttribute("aria-busy");
    }
  }

  // Delegated, so swapped-in fragments keep working without re-binding.
  document.addEventListener("click", function (ev) {
    var el = ev.target.closest("[hx-get]");
    if (!el) return;
    ev.preventDefault();
    request(el);
  });
})();
